1	import crypto from "node:crypto";
     2	import { clearBootstrapSnapshotOnSessionRollover } from "../../agents/bootstrap-cache.js";
     3	import type { OpenClawConfig } from "../../config/config.js";
     4	import {
     5	  evaluateSessionFreshness,
     6	  loadSessionStore,
     7	  resolveSessionResetPolicy,
     8	  resolveStorePath,
     9	  type SessionEntry,
    10	} from "../../config/sessions.js";
    11	
    12	export function resolveCronSession(params: {
    13	  cfg: OpenClawConfig;
    14	  sessionKey: string;
    15	  nowMs: number;
    16	  agentId: string;
    17	  forceNew?: boolean;
    18	}) {
    19	  const sessionCfg = params.cfg.session;
    20	  const storePath = resolveStorePath(sessionCfg?.store, {
    21	    agentId: params.agentId,
    22	  });
    23	  const store = loadSessionStore(storePath);
    24	  const entry = store[params.sessionKey];
    25	
    26	  // Check if we can reuse an existing session
    27	  let sessionId: string;
    28	  let isNewSession: boolean;
    29	  let systemSent: boolean;
    30	
    31	  if (!params.forceNew && entry?.sessionId) {
    32	    // Evaluate freshness using the configured reset policy
    33	    // Cron/webhook sessions use "direct" reset type (1:1 conversation style)
    34	    const resetPolicy = resolveSessionResetPolicy({
    35	      sessionCfg,
    36	      resetType: "direct",
    37	    });
    38	    const freshness = evaluateSessionFreshness({
    39	      updatedAt: entry.updatedAt,
    40	      now: params.nowMs,
    41	      policy: resetPolicy,
    42	    });
    43	
    44	    if (freshness.fresh) {
    45	      // Reuse existing session
    46	      sessionId = entry.sessionId;
    47	      isNewSession = false;
    48	      systemSent = entry.systemSent ?? false;
    49	    } else {
    50	      // Session expired, create new
    51	      sessionId = crypto.randomUUID();
    52	      isNewSession = true;
    53	      systemSent = false;
    54	    }
    55	  } else {
    56	    // No existing session or forced new
    57	    sessionId = crypto.randomUUID();
    58	    isNewSession = true;
    59	    systemSent = false;
    60	  }
    61	
    62	  clearBootstrapSnapshotOnSessionRollover({
    63	    sessionKey: params.sessionKey,
    64	    previousSessionId: isNewSession ? entry?.sessionId : undefined,
    65	  });
    66	
    67	  const sessionEntry: SessionEntry = {
    68	    // Preserve existing per-session overrides even when rolling to a new sessionId.
    69	    ...entry,
    70	    // Always update these core fields
    71	    sessionId,
    72	    updatedAt: params.nowMs,
    73	    systemSent,
    74	    // When starting a fresh session (forceNew / isolated), clear delivery routing
    75	    // state inherited from prior sessions. Without this, lastThreadId leaks into
    76	    // the new session and causes announce-mode cron deliveries to post as thread
    77	    // replies instead of channel top-level messages.
    78	    // deliveryContext must also be cleared because normalizeSessionEntryDelivery
    79	    // repopulates lastThreadId from deliveryContext.threadId on store writes.
    80	    // Model/provider overrides must also be cleared for isolated sessions (forceNew)
    81	    // so that heartbeat.model and cron --model overrides are not blocked by the
    82	    // stored model from a prior session. Without this, hasDifferentLiveSessionModelSelection
    83	    // (or the stored-override path in createModelSelectionState) would override the
    84	    // explicitly-specified heartbeat/cron model with the old session's model.
    85	    ...(isNewSession && {
    86	      lastChannel: undefined,
    87	      lastTo: undefined,
    88	      lastAccountId: undefined,
    89	      lastThreadId: undefined,
    90	      deliveryContext: undefined,
    91	      ...(params.forceNew && {
    92	        modelOverride: undefined,
    93	        providerOverride: undefined,
    94	      }),
    95	    }),
    96	  };
    97	  return { storePath, store, sessionEntry, systemSent, isNewSession };
    98	}

